slides=[]
def cue(cid,body):
 if body.startswith('<div class="screen-note">'):return '<div class="screen-note"><span class="cue" data-cue="'+cid+'">'+body.removeprefix('<div class="screen-note">').removesuffix('</div>')+'</span></div>'
 return f'<div class="cue" data-cue="{cid}">{body}</div>'
def head(tag,title):return f'<div class="tag">{tag}</div><h1>{title}</h1>'
def card(cid,tag,title,body):return '<article class="card"><small>'+tag+'</small>'+cue(cid,f'<h2>{title}</h2><p>{body}</p>')+'</article>'
def add(title,body,segments,cls=''):slides.append({'title':title,'body':body,'segments':segments,'class':cls})
add('Welcome to Claude Managed Agents',head('CLAUDE MANAGED AGENTS · LEARN · BUILD · EXPERIMENT','Welcome &amp; Course Overview')+'<img class="portal-cover" src="assets/portal-welcome.png"><aside class="cover-side">'+cue('managed-welcome','<h2>Your learning journey</h2><p>Understand managed sessions.<br>Build practical applications.<br>Practice through 75 labs.</p>')+'<div class="badge">Luis Coco Enríquez<br><small>Your instructor</small></div></aside>',[('managed-welcome','Welcome to the Claude Managed Agents course. I am your instructor, Luis Coco Enriquez. Together, we will connect the concepts with practical applications and a learning platform where you can run experiments, inspect evidence, and build your understanding step by step. Let me show you the journey ahead.')],'cover')
add('Your course at a glance',head('207 LECTURES · 15 SECTIONS','Concepts, applications and hands-on practice')+'<div class="grid four">'+card('managed-scale-duration','UPLOADED VIDEO','27 hours 56 minutes','Study at your own pace.<br>Pause, revisit and experiment.')+card('managed-scale-pairs','CORE TEACHING SEQUENCE','60 concepts + 60 examples','Understand the idea,<br>then explore its practical application.')+card('managed-scale-labs','LEARNING PLATFORM','75 hands-on labs','Read · run · inspect · reflect.<br>Connect the interface to TypeScript source.')+card('managed-scale-path','YOUR LEARNING ROUTE','From sessions to capstones','Lifecycle, tools, context and trust<br>Teams, reliability and applied agents')+'</div><div class="banner">Udemy lecture numbers, concept/example numbers and platform lab numbers are separate indexes.</div>',[('managed-scale-duration','This course contains two hundred and seven lectures across fifteen sections, with twenty-seven hours and fifty-six minutes of uploaded video. You can study gradually and return to the material when you need it.'),('managed-scale-pairs','The core teaching sequence contains sixty concept lessons and sixty practical example applications. Use each example to connect the explanation to visible application behavior.'),('managed-scale-labs','The learning platform provides seventy-five hands-on labs. These labs have their own numbering, separate from the concept and practical-example sequence and from Udemy lecture numbers.'),('managed-scale-path','The course moves from managed sessions and their lifecycle to tools, context, governance, security, teams, reliability, and applied agent systems.')])
add('Roadmap: introduction, sessions and tools',head('SECTIONS 1–4','Build your Managed Agents foundations')+'<div class="grid four">'+card('managed-route-intro','SECTION 1 · INTRODUCTION','Get oriented','Platform tour · first lab · architecture<br>Guided prompts · TypeScript repository')+card('managed-route-foundations','SECTION 2 · EXAMPLES 1–6','Understand the managed surface','API dictionary · agents and versions · sessions<br>Configuration · environments · retained context')+card('managed-route-lifecycle','SECTION 3 · EXAMPLES 7–13','Follow the session lifecycle','Stop reasons · event routing · stream recovery<br>Message queues · deadlines · cleanup · snapshots')+card('managed-route-context','SECTION 4 · EXAMPLES 14–22','Engineer context and tools','Instructions · compaction · memory stores<br>Tool boundaries · permissions · custom tools')+'</div>',[('managed-route-intro','Section one gets you oriented with the learning platform, your first lab, the application architecture, guided build prompts, and the TypeScript repository.'),('managed-route-foundations','Section two establishes the foundations: the API vocabulary, agents, versions, sessions, configuration, environments, and retained context. You will also compare agent surfaces and study safe rollouts.'),('managed-route-lifecycle','Section three follows the session lifecycle. You will study stop reasons, event routing, stream recovery, message queues, deadlines, cancellation, cleanup, and session inventory.'),('managed-route-context','Section four connects instructions, context growth, compaction, memory stores, and tools. You will distinguish tool availability from permission and see how a host answers custom tool calls.')])
add('Roadmap: integrations, optimization and governance',head('SECTIONS 5–8','Connect capabilities and control execution')+'<div class="grid four">'+card('managed-route-capability','SECTION 5 · EXAMPLES 23–31','Integrations and evaluation','Delegation · offline replay · audit and telemetry<br>MCP · vaults · browser tools · Skills')+card('managed-route-usage','SECTION 6 · EXAMPLES 32–36','Models, usage and outcomes','Models and effort · budgets · prompt caching<br>Routing · verified outcomes · rubric graders')+card('managed-route-human','SECTION 7 · EXAMPLES 37–41','Human decisions and policy','Correlated questions · plans and task boards<br>Channel approvals · interceptors · policy services')+card('managed-route-security','SECTION 8 · EXAMPLES 42–46','Security and trust boundaries','Sandbox versus host · trusted configuration<br>Hardening · prompt injection · safe data access')+'</div>',[('managed-route-capability','Section five covers capabilities and integrations: delegation, evaluation, offline replay, monitoring, MCP connections, vaults, browser tools, and Skills. Keep the feature you are studying connected to its actual execution boundary.'),('managed-route-usage','Section six explores models, effort, usage, budgets, caching, routing, and outcome evaluation. You will learn to compare observed results rather than assuming that a more expensive run is automatically better.'),('managed-route-human','Section seven adds human decisions and execution governance. Topics include correlated answers, plan review, task boards, approvals across channels, lifecycle interceptors, and external policy services.'),('managed-route-security','Section eight examines trust boundaries, configuration, sandboxing, hardening, prompt injection, and safe database access. These topics help you reason about what each part of your system is allowed to do.')])
add('Roadmap: coordinated agents and applied systems',head('SECTIONS 9–13','Coordinate teams and verify real outcomes')+'<div class="grid four">'+card('managed-route-teams','SECTIONS 9–10 · EXAMPLES 47–53','Teams and collaborative workflows','Session threads · orchestration · evidence messages<br>Parallel worktrees · merging · voting · handoffs')+card('managed-route-reliability','SECTION 11 · EXAMPLES 54–55','Observability and reliability','Multi-agent telemetry<br>Offline tests, evaluations and baselines')+card('managed-route-production','SECTION 12 · EXAMPLES 56–58','Production application patterns','Durable and scheduled work · event-driven agents<br>Real-time frontends · SaaS · CI · upgrades')+card('managed-route-capstones','SECTION 13 · EXAMPLES 59–60','Applied agents and capstones','Retrieval · analysis · document generation · review<br>From an application to an engineering team')+'</div>',[('managed-route-teams','Sections nine and ten focus on coordinated work: session threads, model-driven and host-driven orchestration, teams, evidence messages, parallel worktrees, reconciliation, review panels, and handoffs.'),('managed-route-reliability','Section eleven follows that coordination with telemetry, offline testing, evaluations, and regression baselines. You will study how to observe and compare a multi-agent workflow.'),('managed-route-production','Section twelve explores durable and scheduled work, event-driven agents, real-time frontends, multi-tenant architecture, continuous integration, providers, and upgrades.'),('managed-route-capstones','Section thirteen brings the ideas into applied patterns and capstones. The examples connect retrieval, analysis, document generation, and review, then grow toward an autonomous engineering team.')])
add('The platform and optional build-along',head('SECTIONS 14–15','Practice the topics and explore the implementation')+'<div class="grid three">'+card('managed-route-platform','SECTION 14','75 platform labs','Start with session event streaming.<br>Explore tools, context, permissions and teams.<br>Continue through advanced application labs.')+card('managed-route-source','ACROSS THE LABS','Trace the app workflow','Connect the browser to its backend.<br>Read the TypeScript implementation.<br>Inspect both session and host evidence.')+card('managed-route-build','SECTION 15 · OPTIONAL','Build-along foundation','Begin with the development environment.<br>VS Code · Node.js · Claude Code · Codex<br>Use the guided application prompts.')+'</div>',[('managed-route-platform','Section fourteen is the seventy-five-lab learning platform sequence. Start with session event streaming, then use the labs to explore tools, permissions, context, orchestration, and advanced applications.'),('managed-route-source','Connect the interface to its backend and TypeScript source. A useful question is: which session event or host record proves that this step actually happened?'),('managed-route-build','The optional build-along section starts with development environment setup using VS Code, Node, Claude Code, and Codex. Use the guided prompts introduced earlier in the course when you want to study how the application is built.')])
add('Understand the provider and application boundary',head('A CORE MENTAL MODEL','The hosted runtime and your host have different jobs')+'<div class="grid three">'+card('managed-boundary-provider','MANAGED AGENTS SERVICE','Hosted agent execution','Managed sessions and agent loop<br>Configured remote environments<br>Session and lifecycle events')+card('managed-boundary-host','YOUR APPLICATION','Host responsibilities','User interface and application identity<br>Validation, approvals and business policy<br>Custom tool handlers and local integrations')+card('managed-boundary-evidence','VERIFY THE WORKFLOW','Evidence across both sides','Inspect provider events and stop reasons.<br>Check host actions and stored results.<br>Distinguish text from verified effects.')+'</div><div class="banner">An enabled tool, an approved operation and a verified result are different things.</div>',[('managed-boundary-provider','A central idea in this course is the boundary between the hosted runtime and your application. Managed Agents provides hosted agent execution through sessions and configured remote environments, with events that describe what happens.'),('managed-boundary-host','Your application still owns its interface, identity decisions, input validation, approvals, business rules, custom tool handlers, and local integrations. A managed runtime does not remove those application responsibilities.'),('managed-boundary-evidence','Read evidence across both sides. Inspect session events and stop reasons, then check any required host actions and stored results. Fluent agent text alone does not prove that an operation succeeded.')])
add('A repeatable learning pattern',head('CONCEPT → EXAMPLE → LAB → EVIDENCE','Learn one idea, then test your understanding')+'<div class="grid four">'+card('managed-loop-concept','1 · CONCEPT','Understand the responsibility','What does the service manage?<br>What remains under application control?')+card('managed-loop-example','2 · PRACTICAL EXAMPLE','Observe the workflow','Follow the interface, events<br>and application implementation.')+card('managed-loop-lab','3 · HANDS-ON LAB','Change one bounded input','Predict the result before running.<br>Try a small, focused experiment.')+card('managed-loop-evidence','4 · REVIEW','Explain what the evidence proves','Inspect the outcome and host effects.<br>Save a note and revisit unclear steps.')+'</div>',[('managed-loop-concept','Begin each topic by understanding the responsibility: what the service manages and what the application must control.'),('managed-loop-example','Then follow the paired practical example and connect the interface to events and implementation.'),('managed-loop-lab','Use a lab to change one bounded input. Predict the outcome first, so the run answers a specific question.'),('managed-loop-evidence','Finally, inspect the evidence, explain the outcome, and record what you want to revisit. Watching, understanding, and verifying are complementary parts of the learning process.')])
